// Assembles the GitHub Pages site in _site/: the demo page, the browser build
// of the library and the API reference generated by typedoc (docs/).
// Run `npm run site`, which builds dist/ and docs/ first.
import { cpSync, existsSync, mkdirSync, readdirSync, rmSync } from 'node:fs';

for (const required of [
  'dist/base32-key.min.js',
  'dist/template.js',
  'docs/index.html',
]) {
  if (!existsSync(required)) {
    throw new Error(`${required} is missing: run "npm run site"`);
  }
}

rmSync('_site', { recursive: true, force: true });
mkdirSync('_site');
cpSync('site', '_site', { recursive: true });
cpSync('dist/base32-key.min.js', '_site/base32-key.min.js');
cpSync('dist/base32-key.min.js.map', '_site/base32-key.min.js.map');
// base32-key/template and the chunk it shares with the core, for the demo.
for (const file of readdirSync('dist')) {
  if (/^(template|chunk-[\w-]+)\.js$/.test(file)) {
    cpSync(`dist/${file}`, `_site/${file}`);
  }
}
cpSync('docs', '_site/api', { recursive: true });
console.log('Site written to _site/');
